function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 6,
    rows: 5,
    dimTop: 'D',
    dimRight: 'S',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: WEIGHT_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 4,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 6,
    rows: 1,
  });
}

function drawShapeEquation(g: Gsel, cx: number, cy: number, equation: string): void {
  lbl(g, cx, cy + ROW_EQ_GAP, equation, { size: 12, color: COLORS.muted, font: 'monospace' });
}

function drawMatmulRow(
  g: Gsel,
  cx: number,
  cy: number,
  leftLabel: string,
  leftShape: string,
  leftFill: string,
  leftStroke: string,
  weightLabel: string,
  weightShape: string,
  weightFill: string,
  weightStroke: string,
  rightLabel: string,
  rightShape: string,
  rightFill: string,
  rightStroke: string,
  equation: string
): number {
  const leftX = cx - 210;
  const weightX = cx - 40;
  const opX = cx + 115;
  const rightX = cx + 210;
  const outVecW = 110;

  drawSmallVector(g, leftX, cy, leftLabel, leftShape, leftFill, leftStroke);
  drawWeightMatrix(g, weightX, cy, weightLabel, weightShape, weightFill, weightStroke);
  drawSmallVector(g, rightX, cy, rightLabel, rightShape, rightFill, rightStroke, outVecW);

  g.append('circle').attr('cx', opX).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, cy, '@', { size: 13, weight: '700', color: '#64748b' });

  arrowH(g, leftX + VEC_W, opX - 14, cy, leftStroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, cy, weightStroke);
  arrowH(g, opX + 14, rightX, cy, rightStroke);

  drawShapeEquation(g, cx, cy, equation);
  return cy + MAT_H / 2 + ROW_EQ_GAP + 10;
}

function drawParamSummary(
  g: Gsel,
  cx: number,
  y: number,
  dModel: number,
  dFf: number,
  seqLen: number,
  capacityFactor: number,
  selected: number
): number {
  const SUM_W = 960;
  const SUM_H = 72;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect').attr('width', SUM_W).attr('height', SUM_H).attr('rx', 8)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(grp, 18, 20, 'Parameters →', { size: 11, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model=${dModel}`, dim: 'hidden dim', color: '#4caf50' },
    { label: `d_ff=${dFf}`, dim: 'FFN inner', color: '#1976d2' },
    { label: `seq_len=${seqLen}`, dim: 'tokens', color: '#7c3aed' },
    { label: `capacity=${capacityFactor}`, dim: 'active ratio', color: '#d81b60' },
    { label: `selected=${selected}`, dim: 'FFN tokens', color: '#009688' },
    { label: `bypassed=${seqLen - selected}`, dim: 'skip tokens', color: '#f57c00' },
  ];
  const itemW = 154;
  const startX = 18;
  items.forEach((item, i) => {
    const px = startX + i * itemW;
    grp.append('rect').attr('x', px).attr('y', 28).attr('width', itemW - 6).attr('height', 36).attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(grp, px + 9, 46, item.label, { size: 11, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 9, 58, `→ ${item.dim}`, { size: 9, color: item.color, anchor: 'start' });
  });

  return y + SUM_H + 16;
}

