function drawScoreVector(
  g: Gsel,
  cx: number,
  cy: number,
  selected: number,
  seqLen: number
): number {
  const vecW = SEQ_W;
  const vecH = VEC_H;
  const x = cx - vecW / 2;
  const y = cy - vecH / 2;

  drawSmallVector(g, x, cy, 'logits', '[B, S, 1]', COLORS.router.fill, COLORS.router.stroke, vecW);

  // Highlight selected positions in the score vector
  const cellW = (vecW - 2) / 8;
  const pad = 2;
  const nHighlighted = Math.min(selected, 8);
  for (let i = 0; i < nHighlighted; i++) {
    const c = (i * 2 + 1) % 8;
    g.append('rect')
      .attr('x', x + 1 + c * cellW + pad)
      .attr('y', y + 1 + pad)
      .attr('width', cellW - pad * 2)
      .attr('height', vecH - 2 - pad * 2)
      .attr('rx', 2)
      .attr('fill', COLORS.topk.stroke)
      .attr('opacity', 0.28)
      .attr('stroke', COLORS.topk.stroke)
      .attr('stroke-width', 1);
  }

  lbl(g, cx, cy + 30, `top-${selected} of ${seqLen} tokens selected`, { size: 12, color: COLORS.muted, font: 'monospace' });

  // topk operator badge
  const badgeW = 60;
  const badgeCy = cy + 50;
  g.append('rect')
    .attr('x', cx - badgeW / 2).attr('y', badgeCy - VEC_H / 2)
    .attr('width', badgeW).attr('height', VEC_H).attr('rx', 6)
    .attr('fill', COLORS.topk.fill).attr('stroke', COLORS.topk.stroke).attr('stroke-width', 1.5);
  lbl(g, cx, badgeCy, `topk(${selected})`, { size: 10, weight: '600', color: COLORS.topk.stroke });

  // Indices tensor produced by topk
  const idxCy = cy + 74;
  drawSmallVector(g, x, idxCy, 'indices', `[B, ${selected}]`, COLORS.topk.fill, COLORS.topk.stroke, vecW);
  // Highlight the same selected slots
  for (let i = 0; i < nHighlighted; i++) {
    const c = (i * 2 + 1) % 8;
    g.append('rect')
      .attr('x', x + 1 + c * cellW + pad)
      .attr('y', idxCy - vecH / 2 + 1 + pad)
      .attr('width', cellW - pad * 2)
      .attr('height', vecH - 2 - pad * 2)
      .attr('rx', 2)
      .attr('fill', COLORS.topk.stroke)
      .attr('opacity', 0.18)
      .attr('stroke', COLORS.topk.stroke)
      .attr('stroke-width', 1);
  }
  lbl(g, cx, idxCy + 30, 'selected token positions', { size: 12, color: COLORS.muted, font: 'monospace' });

  return idxCy + 46;
}

function drawDepthMask(
  g: Gsel,
  cx: number,
  cy: number,
  selected: number,
  seqLen: number
): number {
  const vecW = SEQ_W;
  const vecH = VEC_H;
  const x = cx - vecW / 2;

  // Input: selected indices from topk
  const idxCy = cy;
  drawSmallVector(g, x, idxCy, 'indices', `[B, ${selected}]`, COLORS.topk.fill, COLORS.topk.stroke, vecW);
  const cellW = (vecW - 2) / 8;
  const pad = 2;
  const nHighlighted = Math.min(selected, 8);
  for (let i = 0; i < nHighlighted; i++) {
    const c = (i * 2 + 1) % 8;
    g.append('rect')
      .attr('x', x + 1 + c * cellW + pad)
      .attr('y', idxCy - vecH / 2 + 1 + pad)
      .attr('width', cellW - pad * 2)
      .attr('height', vecH - 2 - pad * 2)
      .attr('rx', 2)
      .attr('fill', COLORS.topk.stroke)
      .attr('opacity', 0.18)
      .attr('stroke', COLORS.topk.stroke)
      .attr('stroke-width', 1);
  }

  // scatter_ operator badge
  const badgeW = 140;
  const badgeH = VEC_H;
  const badgeCy = idxCy + 52;
  g.append('rect')
    .attr('x', cx - badgeW / 2).attr('y', badgeCy - badgeH / 2)
    .attr('width', badgeW).attr('height', badgeH).attr('rx', 6)
    .attr('fill', COLORS.mask.fill).attr('stroke', COLORS.mask.stroke).attr('stroke-width', 1.5);
  lbl(g, cx, badgeCy, 'scatter_(dim=1, indices, 1)', { size: 10, weight: '600', color: COLORS.mask.stroke });
  arrowDown(g, cx, idxCy + vecH / 2, badgeCy - badgeH / 2, COLORS.topk.stroke);

  // Output: depth_mask vector
  const maskCy = badgeCy + 52;
  drawSmallVector(g, x, maskCy, 'depth_mask', '[B, S, 1]', COLORS.mask.fill, COLORS.mask.stroke, vecW);
  const maskY = maskCy - vecH / 2;
  for (let i = 0; i < nHighlighted; i++) {
    const c = (i * 2 + 1) % 8;
    g.append('rect')
      .attr('x', x + 1 + c * cellW + pad)
      .attr('y', maskY + 1 + pad)
      .attr('width', cellW - pad * 2)
      .attr('height', vecH - 2 - pad * 2)
      .attr('rx', 2)
      .attr('fill', COLORS.mask.stroke)
      .attr('opacity', 0.55)
      .attr('stroke', COLORS.mask.stroke)
      .attr('stroke-width', 1);
  }
  lbl(g, cx, maskCy + 30, `${selected} ones, ${seqLen - selected} zeros`, { size: 12, color: COLORS.muted, font: 'monospace' });
  arrowDown(g, cx, badgeCy + badgeH / 2, maskCy - vecH / 2, COLORS.mask.stroke);

  return maskCy + 48;
}

function drawSplitBoxes(
  g: Gsel,
  cx: number,
  cy: number,
  selected: number,
  bypassed: number
): number {
  const boxW = 190;
  const boxH = 76;
  const gap = 44;
  const totalW = 2 * boxW + gap;
  const startX = cx - totalW / 2;

  // Selected box
  const selG = g.append('g');
  selG.append('rect')
    .attr('x', startX).attr('y', cy - boxH / 2)
    .attr('width', boxW).attr('height', boxH).attr('rx', 8)
    .attr('fill', COLORS.selected.fill).attr('stroke', COLORS.selected.stroke).attr('stroke-width', 1.5);
  selG.append('rect')
    .attr('x', startX + 10).attr('y', cy - boxH / 2 + 34)
    .attr('width', boxW - 20).attr('height', 26).attr('rx', 5)
    .attr('fill', '#fff').attr('stroke', COLORS.selected.stroke).attr('stroke-width', 1);
  lbl(selG, startX + boxW / 2, cy - boxH / 2 + 20, 'Selected tokens', { size: 13, weight: '600', color: COLORS.selected.stroke });
  lbl(selG, startX + boxW / 2, cy - boxH / 2 + 48, `x_sel  [B, ${selected}, D]`, { size: 10, color: COLORS.muted, font: 'monospace' });

  // Bypass box
  const bypG = g.append('g');
  bypG.append('rect')
    .attr('x', startX + boxW + gap).attr('y', cy - boxH / 2)
    .attr('width', boxW).attr('height', boxH).attr('rx', 8)
    .attr('fill', COLORS.bypass.fill).attr('stroke', COLORS.bypass.stroke).attr('stroke-width', 1.5);
  bypG.append('rect')
    .attr('x', startX + boxW + gap + 10).attr('y', cy - boxH / 2 + 34)
    .attr('width', boxW - 20).attr('height', 26).attr('rx', 5)
    .attr('fill', '#fff').attr('stroke', COLORS.bypass.stroke).attr('stroke-width', 1);
  lbl(bypG, startX + boxW + gap + boxW / 2, cy - boxH / 2 + 20, 'Bypassed tokens', { size: 13, weight: '600', color: COLORS.bypass.stroke });
  lbl(bypG, startX + boxW + gap + boxW / 2, cy - boxH / 2 + 48, `x_byp  [B, ${bypassed}, D]`, { size: 10, color: COLORS.muted, font: 'monospace' });

  return cy + boxH / 2 + 26;
}

function drawFfnFlow(g: Gsel, cx: number, cy: number): number {
  // Vertical FFN pipeline for the selected tokens.
  const vecW = 110;
  const inputX = cx - 200;
  const weightX = cx - 35;
  const opX = cx + 115;
  const outX = cx + 200;
  const rowGap = 82;

  // Stage 1: x_sel @ W_up → h
  drawSmallVector(g, inputX, cy, 'x_sel', '[B, C, D]', COLORS.selected.fill, COLORS.selected.stroke, vecW);
  drawWeightMatrix(g, weightX, cy, 'W_up', '[D, d_ff]', COLORS.ffn.fill, COLORS.ffn.stroke);
  drawSmallVector(g, outX, cy, 'h', '[B, C, d_ff]', COLORS.ffn.fill, COLORS.ffn.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, cy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowH(g, inputX + vecW, opX - 14, cy, COLORS.selected.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, cy, COLORS.ffn.stroke);
  arrowH(g, opX + 14, outX, cy, COLORS.ffn.stroke);
  drawShapeEquation(g, cx, cy, '[B, C, D] @ [D, d_ff] → [B, C, d_ff]');

  // Stage 2: SiLU activation
  const actCy = cy + VEC_H / 2 + rowGap;
  const badgeW = 66;
  const badgeX = outX - badgeW - 16;
  drawSmallVector(g, outX, actCy, 'h', '[B, C, d_ff]', COLORS.ffn.fill, COLORS.ffn.stroke, vecW);
  g.append('rect')
    .attr('x', badgeX).attr('y', actCy - VEC_H / 2)
    .attr('width', badgeW).attr('height', VEC_H).attr('rx', 6)
    .attr('fill', COLORS.activation.fill).attr('stroke', COLORS.activation.stroke).attr('stroke-width', 1.5);
  lbl(g, badgeX + badgeW / 2, actCy, 'SiLU', { size: 10, weight: '600', color: COLORS.activation.stroke });
  drawSmallVector(g, inputX, actCy, 'a', '[B, C, d_ff]', COLORS.activation.fill, COLORS.activation.stroke, vecW);
  arrowH(g, outX, badgeX + badgeW, actCy, COLORS.ffn.stroke);
  arrowH(g, badgeX, inputX + vecW, actCy, COLORS.activation.stroke);
  lbl(g, cx, actCy + VEC_H / 2 + 20, 'SiLU non-linearity', { size: 11, color: COLORS.muted });

  // Stage 3: a @ W_down → ffn_out
  const downCy = actCy + VEC_H / 2 + rowGap;
  drawSmallVector(g, inputX, downCy, 'a', '[B, C, d_ff]', COLORS.activation.fill, COLORS.activation.stroke, vecW);
  drawWeightMatrix(g, weightX, downCy, 'W_down', '[d_ff, D]', COLORS.weight.fill, COLORS.weight.stroke);
  drawSmallVector(g, outX, downCy, 'ffn_out', '[B, C, D]', COLORS.selected.fill, COLORS.selected.stroke, vecW);
  g.append('circle').attr('cx', opX).attr('cy', downCy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, downCy, '@', { size: 13, weight: '700', color: '#64748b' });
  arrowH(g, inputX + vecW, opX - 14, downCy, COLORS.activation.stroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, downCy, COLORS.weight.stroke);
  arrowH(g, opX + 14, outX, downCy, COLORS.selected.stroke);
  drawShapeEquation(g, cx, downCy, '[B, C, d_ff] @ [d_ff, D] → [B, C, D]');

  return downCy + MAT_H / 2 + ROW_EQ_GAP + 10;
}

function drawBypassBox(g: Gsel, cx: number, cy: number, bypassed: number): number {
  const boxW = 220;
  const boxH = 76;
  const x = cx - boxW / 2;
  const y = cy - boxH / 2;

  g.append('rect')
    .attr('x', x).attr('y', y)
    .attr('width', boxW).attr('height', boxH).attr('rx', 10)
    .attr('fill', COLORS.bypass.fill).attr('stroke', COLORS.bypass.stroke).attr('stroke-width', 2);
  g.append('rect')
    .attr('x', x + 14).attr('y', y + 36)
    .attr('width', boxW - 28).attr('height', 28).attr('rx', 6)
    .attr('fill', '#fff').attr('stroke', COLORS.bypass.stroke).attr('stroke-width', 1);
  lbl(g, cx, y + 24, 'Identity Bypass', { size: 14, weight: '600', color: COLORS.bypass.stroke });
  lbl(g, cx, y + 54, `x_byp  [B, ${bypassed}, D]`, { size: 10, color: COLORS.muted, font: 'monospace' });

  return cy + boxH / 2 + 18;
}

function drawMergeScatter(
  g: Gsel,
  cx: number,
  cy: number,
  selected: number,
  bypassed: number
): number {
  const boxW = 190;
  const boxH = 76;
  const gap = 44;
  const totalW = 2 * boxW + gap;
  const startX = cx - totalW / 2;

  // Input: ffn_out and bypass_out
  const ffnG = g.append('g');
  ffnG.append('rect')
    .attr('x', startX).attr('y', cy - boxH / 2)
    .attr('width', boxW).attr('height', boxH).attr('rx', 8)
    .attr('fill', COLORS.selected.fill).attr('stroke', COLORS.selected.stroke).attr('stroke-width', 1.5);
  lbl(ffnG, startX + boxW / 2, cy - 12, 'ffn_out', { size: 12, weight: '600', color: COLORS.selected.stroke });
  lbl(ffnG, startX + boxW / 2, cy + 14, `[B, ${selected}, D]`, { size: 10, color: COLORS.muted, font: 'monospace' });

  const bypG = g.append('g');
  bypG.append('rect')
    .attr('x', startX + boxW + gap).attr('y', cy - boxH / 2)
    .attr('width', boxW).attr('height', boxH).attr('rx', 8)
    .attr('fill', COLORS.bypass.fill).attr('stroke', COLORS.bypass.stroke).attr('stroke-width', 1.5);
  lbl(bypG, startX + boxW + gap + boxW / 2, cy - 12, 'bypass_out', { size: 12, weight: '600', color: COLORS.bypass.stroke });
  lbl(bypG, startX + boxW + gap + boxW / 2, cy + 14, `[B, ${bypassed}, D]`, { size: 10, color: COLORS.muted, font: 'monospace' });

  // Scatter/merge circle
  const circleCy = cy + boxH / 2 + 40;
  g.append('circle').attr('cx', cx).attr('cy', circleCy).attr('r', 22)
    .attr('fill', '#fff').attr('stroke', COLORS.merge.stroke).attr('stroke-width', 2);
  lbl(g, cx, circleCy, '⇄', { size: 18, weight: '700', color: COLORS.merge.stroke });

  drawArrow(g as Sel, startX + boxW / 2, cy + boxH / 2, cx - 14, circleCy - 14, { color: COLORS.selected.stroke });
  drawArrow(g as Sel, startX + boxW + gap + boxW / 2, cy + boxH / 2, cx + 14, circleCy - 14, { color: COLORS.bypass.stroke });

  // Output merged tensor
  const outCy = circleCy + 64;
  drawSeqMatrix(g, cx - 75, outCy, 'merged', '[B, S, D]', COLORS.merge.fill, COLORS.merge.stroke);
  arrowDown(g, cx, circleCy + 22, outCy - MAT_H / 2, COLORS.merge.stroke);

  lbl(g, cx, outCy + MAT_H / 2 + 20, 'place outputs back to original positions', { size: 12, color: COLORS.muted });
  return outCy + MAT_H / 2 + 38;
}

function drawResidualAdd(g: Gsel, cx: number, cy: number): number {
  const inputX = cx - 180;
  const moeX = cx - 10;
  const plusX = cx + 100;
  const outX = cx + 200;

  drawSmallVector(g, inputX, cy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  drawSmallVector(g, moeX, cy, 'merged', '[B, S, D]', COLORS.merge.fill, COLORS.merge.stroke);

  g.append('circle').attr('cx', plusX).attr('cy', cy).attr('r', 18)
    .attr('fill', '#fff').attr('stroke', COLORS.residual.stroke).attr('stroke-width', 2);
  lbl(g, plusX, cy, '+', { size: 18, weight: '700', color: COLORS.residual.stroke });

  arrowH(g, inputX + VEC_W, plusX - 18, cy, COLORS.input.stroke);
  arrowH(g, moeX + VEC_W, plusX - 18, cy, COLORS.merge.stroke);

  drawSmallVector(g, outX, cy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  arrowH(g, plusX + 18, outX, cy, COLORS.residual.stroke);
  lbl(g, cx + 20, cy + 34, 'residual add', { size: 12, color: COLORS.muted });

  return cy + VEC_H / 2 + 36;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Column renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderLeftColumn(
  _g: Gsel,
  yL: number,
  selected: number,
  seqLen: number
): { yL: number; steps: ModStep[] } {
  const steps: ModStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inHeaderBottom = stepHeader(inputGrp, CX_L, yL, 1, 'Input hidden states', 'x ∈ ℝ^(B×S×D)', COLORS.input.fill, COLORS.input.stroke);
  const inCy = inHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(inputGrp, CX_L - 75, inCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(inputGrp, CX_L, inCy + MAT_H / 2 + 18, 'each row = one token embedding', { size: 12, color: COLORS.muted });
  yL = inCy + MAT_H / 2 + GROUP_GAP;

  // 2. Router gate projection
  steps.push({ ...BASE_STEPS.router, id: 2 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.router.stroke);
  yL += GROUP_GAP;
  const routerGrp = startGroup(_g, STEP_GROUPS.router, 2);
  const routerHeaderBottom = stepHeader(routerGrp, CX_L, yL, 2, 'Depth router projection', 'logits = x · W_router', COLORS.router.fill, COLORS.router.stroke);
  const routerRowCy = routerHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const routerBottom = drawMatmulRow(
    routerGrp, CX_L, routerRowCy,
    'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_router', '[D, 1]', COLORS.weight.fill, COLORS.weight.stroke,
    'logits', '[B, S, 1]', COLORS.router.fill, COLORS.router.stroke,
    '[B, S, D] @ [D, 1] → [B, S, 1]'
  );
  yL = routerBottom + GROUP_GAP;

  // 3. Top-C% selection
  steps.push({ ...BASE_STEPS.topk, id: 3 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.topk.stroke);
  yL += GROUP_GAP;
  const topkGrp = startGroup(_g, STEP_GROUPS.topk, 3);
  const topkHeaderBottom = stepHeader(topkGrp, CX_L, yL, 3, 'Top-C% token selection', `indices = topk(logits, ${selected})`, COLORS.topk.fill, COLORS.topk.stroke);
  const topkVecCy = topkHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const topkBottom = drawScoreVector(topkGrp, CX_L, topkVecCy, selected, seqLen);
  yL = topkBottom + GROUP_GAP;

  // 4. Depth mask
  steps.push({ ...BASE_STEPS.mask, id: 4 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.mask.stroke);
  yL += GROUP_GAP;
  const maskGrp = startGroup(_g, STEP_GROUPS.mask, 4);
  const maskHeaderBottom = stepHeader(maskGrp, CX_L, yL, 4, 'Depth mask', 'depth_mask.scatter_(1, indices, 1)', COLORS.mask.fill, COLORS.mask.stroke);
  const maskVecCy = maskHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const maskBottom = drawDepthMask(maskGrp, CX_L, maskVecCy, selected, seqLen);
  yL = maskBottom + GROUP_GAP;

  return { yL, steps };
}

function renderRightColumn(
  _g: Gsel,
  yR: number,
  selected: number,
  bypassed: number
): { yR: number; steps: ModStep[] } {
  const steps: ModStep[] = [];

  // 5. Split
  steps.push({ ...BASE_STEPS.split, id: 5 });
  const splitGrp = startGroup(_g, STEP_GROUPS.split, 5);
  const splitHeaderBottom = stepHeader(splitGrp, CX_R, yR, 5, 'Split selected / bypassed', 'x_sel, x_byp = split(x, mask)', COLORS.split.fill, COLORS.split.stroke);
  const splitCy = splitHeaderBottom + HEADER_TO_ROW_GAP + 36;
  const splitBottom = drawSplitBoxes(splitGrp, CX_R, splitCy, selected, bypassed);
  yR = splitBottom + GROUP_GAP;

  // 6. Selected-token FFN
  steps.push({ ...BASE_STEPS.selected, id: 6 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.selected.stroke);
  const selectedGrp = startGroup(_g, STEP_GROUPS.selected, 6);
  const selectedHeaderBottom = stepHeader(selectedGrp, CX_R, yR, 6, 'Selected-token FFN', 'ffn_out = FFN(x_sel)', COLORS.selected.fill, COLORS.selected.stroke);
  const ffnCy = selectedHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const ffnBottom = drawFfnFlow(selectedGrp, CX_R, ffnCy);
  yR = ffnBottom + GROUP_GAP;

  // 7. Bypass identity path
  steps.push({ ...BASE_STEPS.bypass, id: 7 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.bypass.stroke);
  const bypassGrp = startGroup(_g, STEP_GROUPS.bypass, 7);
  const bypassHeaderBottom = stepHeader(bypassGrp, CX_R, yR, 7, 'Bypass identity path', 'bypass_out = x_byp', COLORS.bypass.fill, COLORS.bypass.stroke);
  const bypassCy = bypassHeaderBottom + HEADER_TO_ROW_GAP + 38;
  const bypassBottom = drawBypassBox(bypassGrp, CX_R, bypassCy, bypassed);
  yR = bypassBottom + GROUP_GAP;

  // 8. Merge / scatter
  steps.push({ ...BASE_STEPS.merge, id: 8 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.merge.stroke);
  const mergeGrp = startGroup(_g, STEP_GROUPS.merge, 8);
  const mergeHeaderBottom = stepHeader(mergeGrp, CX_R, yR, 8, 'Scatter / merge back', 'merged = scatter(ffn_out, bypass_out)', COLORS.merge.fill, COLORS.merge.stroke);
  const mergeCy = mergeHeaderBottom + HEADER_TO_ROW_GAP + 36;
  const mergeBottom = drawMergeScatter(mergeGrp, CX_R, mergeCy, selected, bypassed);
  yR = mergeBottom + GROUP_GAP;

  // 9. Residual add
  steps.push({ ...BASE_STEPS.residual, id: 9 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.residual.stroke);
  const residualGrp = startGroup(_g, STEP_GROUPS.residual, 9);
  const residualHeaderBottom = stepHeader(residualGrp, CX_R, yR, 9, 'Residual connection', 'out = x + merged', COLORS.residual.fill, COLORS.residual.stroke);
  const residualCy = residualHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const residualBottom = drawResidualAdd(residualGrp, CX_R, residualCy);
  yR = residualBottom + GROUP_GAP;

  return { yR, steps };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderMixtureOfDepthsDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const dFf = Number(params.d_ff) || 2048;
  const seqLen = Number(params.seq_len) || 128;
  const capacityFactor = Number(params.capacity_factor) || 0.5;
  const selected = Math.max(1, Math.round(seqLen * capacityFactor));
  const bypassed = seqLen - selected;

  const root = g as unknown as Gsel;
  let y = 30;

  // Title
  lbl(root, CX, y, 'Mixture of Depths', { size: 20, weight: '700', color: COLORS.text });
  y += 24;
  lbl(root, CX, y, `d_model=${dModel}  d_ff=${dFf}  seq_len=${seqLen}  capacity_factor=${capacityFactor}`, {
    size: 12,
    color: COLORS.muted,
  });
  y += 30;

  // Param summary
  y = drawParamSummary(root, CX, y, dModel, dFf, seqLen, capacityFactor, selected);
  y += 24;

  const columnTop = y;

  // Left column: routing decision (Input → Router → Top-C% → Mask)
  const leftResult = renderLeftColumn(root, columnTop, selected, seqLen);

  // Right column: execution path (Split → FFN → Bypass → Merge → Residual → Output)
  const rightResult = renderRightColumn(root, columnTop, selected, bypassed);

  // Cross-column elbow arrow: depth mask drives the split
  const maskOutY = leftResult.yL - GROUP_GAP - 10;
  const splitInY = columnTop + HEADER_H + HEADER_TO_ROW_GAP + 36;
  const midX = CX - 40; // in the inter-column gap
  drawArrow(g, CX_L + 75, maskOutY, midX, maskOutY, { color: COLORS.mask.stroke });
  drawArrow(g, midX, maskOutY, midX, splitInY, { color: COLORS.mask.stroke });
  lbl(root, midX + 8, (maskOutY + splitInY) / 2, 'mask controls split', {
    size: 10,
    color: COLORS.mask.stroke,
    anchor: 'start'
  });

  // Combine steps from both columns
  const steps = [...leftResult.steps, ...rightResult.steps].sort((a, b) => a.id - b.id);

  // 10. Output (full-width, centered under both columns)
  steps.push({ ...BASE_STEPS.output, id: 10 });
  const outputY = Math.max(leftResult.yL, rightResult.yR) + 20;
  arrowDown(root, CX_R, outputY - 20, outputY, COLORS.output.stroke);
  const outGrp = startGroup(root, STEP_GROUPS.output, 10);
  const outHeaderBottom = stepHeader(outGrp, CX, outputY, 10, 'Output hidden states', 'out ∈ ℝ^(B×S×D)', COLORS.output.fill, COLORS.output.stroke);
  const outCy = outHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(outGrp, CX - 75, outCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  let footerY = outCy + MAT_H / 2 + 30;

  // Footer summary
  const routerParams = dModel * 1;
  const ffnParams = 2 * dModel * dFf;
  const totalParams = routerParams + ffnParams;
  const activeFlops = selected * (4 * dModel * dFf) / seqLen;
  const summaryGrp = root.append('g');
  lbl(summaryGrp, CX, footerY + 18, `Params: router ${fmtNum(routerParams)} + FFN ${fmtNum(ffnParams)} = ${fmtNum(totalParams)} · active FLOPs/token ≈ ${fmtNum(activeFlops)}`, {
    size: 11,
    color: COLORS.muted,
  });
  footerY += 38;

  // Side-by-side explanations
  const insightW = (W - 160) / 2;
  const insightY = drawExplanation(g, 80, footerY, insightW - 20,
    'Mixture of Depths dynamically skips the FFN for low-importance tokens. ' +
    `Only the top-${selected} tokens (${Math.round(capacityFactor * 100)}% of the sequence) ` +
    'are routed through the full FFN; the rest take an identity bypass. This reduces active compute ' +
    'while preserving model depth for the most informative tokens.',
    'insight'
  );
  const perfY = drawExplanation(g, 80 + insightW, footerY, insightW - 20,
    `Active FLOPs per token ≈ ${fmtNum(activeFlops)} (capacity-factor ${capacityFactor}). ` +
    'Bypassed tokens avoid the FFN entirely, cutting memory bandwidth and compute. ' +
    'Load balancing across the selected subset is important for efficient batched execution.',
    'perf'
  );
  footerY = Math.max(insightY, perfY) + 18;

  // Cross-link
  drawComponentLink(g, CX - 90, footerY, 180, 32, 'moe-layer', 'View MoE Layer ↗', {
    fill: '#ede9fe',
    stroke: '#7c3aed',
  });
  footerY += 50;

  // Code annotation
  const codeLines = buildCodeLines(dModel, dFf, selected);
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    'Mixture of Depths — Dynamic Token Skipping',
    [`Total params: ${fmtNum(totalParams)}. Active FLOPs per token: ~${fmtNum(activeFlops)}.`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps };
}

function buildCodeLines(
  dModel: number,
  dFf: number,
  selected: number
): string[] {
  return [
    `self.W_router = nn.Linear(${dModel}, 1, bias=False)`,
    `self.ffn = nn.Sequential(`,
    `    nn.Linear(${dModel}, ${dFf}),`,
    `    nn.SiLU(),`,
    `    nn.Linear(${dFf}, ${dModel})`,
    `)`,
    '',
    'def forward(self, x):',
    `    logits = self.W_router(x)                # [B, S, 1]`,
    `    indices = logits.topk(${selected}, dim=1).indices  # [B, ${selected}, 1]`,
    '    mask = torch.zeros(B, S, 1)',
    '    mask.scatter_(1, indices, 1)             # [B, S, 1]',
    '    # Diagram uses batched shapes; boolean indexing below flattens batch dim',
    '    x_sel = x[mask.expand_as(x).bool()]      # [B*C, D]  (diagram: [B, C, D])',
    '    x_byp = x[~mask.expand_as(x).bool()]     # [B*(S-C), D]  (diagram: [B, S-C, D])',
    '    ffn_out = self.ffn(x_sel)                # [B*C, D]',
    '    bypass_out = x_byp                       # [B*(S-C), D]',
    '    merged = torch.zeros_like(x)             # [B, S, D]',
    '    merged[mask.expand_as(x).bool()] = ffn_out',
    '    merged[~mask.expand_as(x).bool()] = bypass_out',
    '    return x + merged                        # [B, S, D]',
  ];
}
